import type { Href } from 'expo-router';

/**
 * Links to dynamic screens. Expo Router's typed-route list is regenerated by the dev server, so
 * these keep type-checking stable for screens added since the last regeneration.
 */
export const routes = {
  profile: (username: string) => `/profile/${encodeURIComponent(username)}` as Href,
  editPost: (id: string) => `/edit-post/${encodeURIComponent(id)}` as Href,
};
